# knob: generated by ShapeBridge (https://github.com/gazi-faysal-jubayer/shapebridge)
# Units: mm. Edit the parameters below; geometry updates from them.

import math
import cadquery as cq

# sketch planes: (x direction, normal); the normal is x × y
FRAMES = {"XY": ((1, 0, 0), (0, 0, 1)), "XZ": ((1, 0, 0), (0, -1, 0)), "YZ": ((0, 1, 0), (1, 0, 0))}


def plane(base, offset):
    x, n = FRAMES[base]
    return cq.Workplane(cq.Plane(origin=tuple(c * offset for c in n), xDir=x, normal=n))


def build(r=15, h=18, grip=2, shaft_d=6):
    # body
    def tool_body():
        return plane("XZ", 0).polyline([(0, 0), (r, 0), (r, h * 0.7), (r * 0.6, h), (0, h)]).close().revolve(360, (0, 0, 0), (0, 1, 0))
    result = tool_body()
    # flute
    def tool_flute():
        return plane("XY", 0).moveTo(r + grip * 0.4, 0).circle(grip).extrude(h * 0.7)
    result = result.cut(tool_flute())
    # flutes
    for i in range(1, int(12)):
        result = result.cut(tool_flute().rotate((0, 0, 0), (0, 0, 1), 360 * i / 12))
    # shaft
    def tool_shaft():
        solids = []
        top = cq.Vector(0, 0, h * 0.6) + cq.Vector((0, 0, 1)) * 0.0001
        solids.append(cq.Solid.makeCylinder(shaft_d / 2, h * 0.6 + 0.0001, top, cq.Vector((0, 0, -1))))
        return cq.Workplane().add(solids[0].fuse(*solids[1:]) if len(solids) > 1 else solids[0])
    result = result.cut(tool_shaft())
    return result


result = build()
if "show_object" in globals():
    show_object(result)
elif __name__ == "__main__":
    cq.exporters.export(result, "knob.step")
